import{_ as a,o as e,c as i,a0 as n}from"./chunks/framework.CLylLE9s.js";const k=JSON.parse('{"title":"How to add docs to your project","description":"","frontmatter":{},"headers":[],"relativePath":"consumers/add-docs.md","filePath":"consumers/add-docs.md"}'),t={name:"consumers/add-docs.md"};function o(p,s,l,d,h,c){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="how-to-add-docs-to-your-project" tabindex="-1">How to add docs to your project <a class="header-anchor" href="#how-to-add-docs-to-your-project" aria-label="Permalink to &quot;How to add docs to your project&quot;">​</a></h1><p>The docs site is a small, independent VitePress project. It can sit alongside a Java, Go, or other non-Node application without changing the project&#39;s build system.</p><h2 id="copy-the-docs-project" tabindex="-1">Copy the docs project <a class="header-anchor" href="#copy-the-docs-project" aria-label="Permalink to &quot;Copy the docs project&quot;">​</a></h2><p>Copy the <code>docs/</code> directory from gh-docs into your repository. It includes the VitePress config and theme, Markdown pages, and its own npm manifest and lockfile:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>  src/                         # Your application, unchanged</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    package.json</span></span>
<span class="line"><span>    package-lock.json</span></span>
<span class="line"><span>    index.md</span></span>
<span class="line"><span>    .vitepress/</span></span>
<span class="line"><span>      config.mts</span></span>
<span class="line"><span>      theme/</span></span></code></pre></div><p>Replace the example pages with your project documentation. Keep <code>package.json</code> and <code>package-lock.json</code> in <code>docs/</code>; commands such as <code>npm ci --prefix docs</code> install the documentation tools without adding a manifest to the repository root.</p><p>Edit <code>docs/.vitepress/config.mts</code> to set the site title, description, sidebar, and navigation. The sidebar links to each page using its path under <code>docs/</code> without the <code>.md</code> extension.</p><h2 id="write-a-page" tabindex="-1">Write a page <a class="header-anchor" href="#write-a-page" aria-label="Permalink to &quot;Write a page&quot;">​</a></h2><p>Create a Markdown file, for example <code>docs/guides/deployment.md</code>:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Deploy the application</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Describe the goal and assumptions.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Prerequisites</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Access to the deployment environment</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The application has passed its tests</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Deploy to staging</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`bash</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">./deploy.sh --environment staging</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Warning**</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; Call out steps that can overwrite data or affect production.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">For local docs development, see [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Run docs locally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./run-locally.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span></span></code></pre></div><p>Use one <code>#</code> title per page and <code>##</code> headings for sections. Add a language after the opening code fence (such as <code>bash</code>, <code>java</code>, <code>go</code>, <code>yaml</code>, or <code>json</code>) for syntax highlighting. Use relative Markdown links for other pages.</p><h2 id="add-the-page-to-navigation" tabindex="-1">Add the page to navigation <a class="header-anchor" href="#add-the-page-to-navigation" aria-label="Permalink to &quot;Add the page to navigation&quot;">​</a></h2><p>Add a sidebar entry in <code>docs/.vitepress/config.mts</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Guides&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  items</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { text: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Deployment&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, link: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/guides/deployment&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The link <code>/guides/deployment</code> corresponds to <code>docs/guides/deployment.md</code>. For grouped pages, nest more entries under an item. Put images or other static files in <code>docs/public/</code> and reference an image as <code>/diagram.png</code>.</p><h2 id="install-docs-dependencies" tabindex="-1">Install docs dependencies <a class="header-anchor" href="#install-docs-dependencies" aria-label="Permalink to &quot;Install docs dependencies&quot;">​</a></h2><p>Run this from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>The docs-only lockfile keeps the documentation tool versions reproducible. It does not install or modify your application&#39;s dependencies.</p><h2 id="choose-a-workflow-reuse-approach" tabindex="-1">Choose a workflow reuse approach <a class="header-anchor" href="#choose-a-workflow-reuse-approach" aria-label="Permalink to &quot;Choose a workflow reuse approach&quot;">​</a></h2><ul><li><strong>Copy the reusable workflow</strong> into your repository if you want it to work independently.</li><li><strong>Call the reusable workflow</strong> from the gh-docs repository if you want centralized fixes and updates. GitHub must be able to access the workflow repository; pin the call to a reviewed commit SHA for stronger supply-chain control.</li></ul><p>The next guide shows both the caller workflow setup and how publishing and cleanup work.</p>`,22)])])}const g=a(t,[["render",o]]);export{k as __pageData,g as default};
